.message-input-area {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem;
    border-top: 1px solid #2d2f34;
    background: #2b2d31;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-textarea {
    flex: 1;
    resize: none;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 0.75rem;
    color: #dcddde;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    min-height: 2.2rem;
    max-height: 8rem;
}

.message-textarea::placeholder {
    color: #72767d;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 1rem;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

