@using sv_646ad44d33d543c49b4313c2d6c6d000.Services

<div class="message-list" @onscroll="HandleScroll" @ref="scrollContainer">
    @if (IsLoadingMore)
    {
        <div class="load-more-indicator">Loading older messages…</div>
    }
    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ReplyCount="GetReplyCount(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference scrollContainer;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);

    private async Task HandleScroll()
    {
        // JS interop would be ideal, but we use a simple approach:
        // trigger load more when scrolled near top
        await OnLoadMore.InvokeAsync();
    }
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.load-more-indicator {
    text-align: center;
    padding: 0.75rem;
    color: #8b949e;
    font-size: 0.8rem;
}

@using sv_646ad44d33d543c49b4313c2d6c6d000.Services
@inject IJSRuntime JS

<div class="message-area">
    <div class="area-header">
        <h2># @Channel.Name</h2>
        <span class="area-description">@Channel.Description</span>
    </div>

    <MessageList Messages="Messages"
                 ThreadReplyCounts="ThreadReplyCounts"
                 IsLoadingMore="IsLoadingMore"
                 OnOpenThread="OnOpenThread"
                 OnReact="OnReact"
                 OnLoadMore="OnLoadMore" />

    <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                  ButtonLabel="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
    background: #313338;
}

.area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #2d2f34;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
    font-weight: 700;
}

.area-description {
    font-size: 0.8rem;
    color: #8b949e;
    margin-top: 0.1rem;
    display: block;
}

@using sv_646ad44d33d543c49b4313c2d6c6d000.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    <div class="thread-root-quote">
        <span class="quote-author">@RootMessage.Author</span>
        <p class="quote-content">@RootMessage.Content</p>
    </div>

    <div class="thread-replies">
        @if (ThreadMessages.Count == 0)
        {
            <div class="no-replies">No replies yet</div>
        }
        else
        {
            @foreach (var msg in ThreadMessages)
            {
                <MessageBubble Message="msg" ShowActions="false" />
            }
        }
    </div>

    <MessageInput Placeholder="Reply in thread…"
                  ButtonLabel="Reply"
                  OnSend="OnSendReply" />
</div>

@code {
    [Parameter, EditorRequired] public Message RootMessage { get; set; } = default!;
    [Parameter, EditorRequired] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2b2d31;
    border-left: 1px solid #2d2f34;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #2d2f34;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
    font-weight: 700;
}

.close-btn {
    background: transparent;
    border: none;
    color: #8b949e;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 4px;
    line-height: 1;
    transition: color 0.15s, background 0.15s;
}

.close-btn:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.1);
}

.thread-root-quote {
    padding: 0.6rem 0.75rem;
    margin: 0.5rem 0.75rem;
    background: rgba(255, 255, 255, 0.04);
    border-left: 3px solid #5865f2;
    border-radius: 0 6px 6px 0;
}

.quote-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.85rem;
}

.quote-content {
    margin: 0.2rem 0 0;
    color: #c9d1d9;
    font-size: 0.85rem;
    line-height: 1.4;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

.no-replies {
    text-align: center;
    padding: 2rem;
    color: #8b949e;
    font-size: 0.85rem;
}

