arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_646ad44d33d543c49b4313c2d6c6d000.Services
@inject IChatService ChatService
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="activeChannel?.Id"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(threadRootMessage is not null ? "" : "expanded")">
        @if (activeChannel is not null)
        {
            <MessageArea Channel="activeChannel"
                         Messages="messages"
                         ThreadReplyCounts="threadReplyCounts"
                         IsLoadingMore="isLoadingMore"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnLoadMore="LoadOlderMessages"
                         OnSendMessage="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         ThreadMessages="threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> channels = [];
    private Channel? activeChannel;
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private bool isLoadingMore;
    private bool hasMoreMessages = true;

    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    private IJSObjectReference? scrollModule;
    private DotNetObjectReference<ChatPage>? dotNetRef;
    private CancellationTokenSource cts = new();

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            scrollModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Pages/Chat/ChatPage.razor.js");
            dotNetRef = DotNetObjectReference.Create(this);
            await scrollModule.InvokeVoidAsync("initScrollDetection", ".chat-main .message-list", dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        await LoadOlderMessages();
        StateHasChanged();
    }

    private async Task SelectChannel(Channel channel)
    {
        activeChannel = channel;
        messages = [];
        threadReplyCounts = [];
        hasMoreMessages = true;
        CloseThreadSync();

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        hasMoreMessages = messages.Count == PageSize;
        await ComputeThreadCounts();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to clear unread badge
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore || !hasMoreMessages || activeChannel is null) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannel.Id, messages.Count, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;
        messages.InsertRange(0, older);
        await ComputeThreadCounts();
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(activeChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void CloseThreadSync()
    {
        threadRootMessage = null;
        threadMessages = [];
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannel.Id, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        // Update thread reply count
        threadReplyCounts[threadRootMessage.Id] = threadMessages.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (activeChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(activeChannel.Id, 0, messages.Count);
        }
    }

    private async Task ComputeThreadCounts()
    {
        // Build thread reply counts from messages that are replies
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        var replyCounts = messages
            .Where(m => m.ReplyToId.HasValue && rootIds.Contains(m.ReplyToId.Value))
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        // Also check threads for messages that have replies outside the current page
        foreach (var rootId in rootIds)
        {
            if (!replyCounts.ContainsKey(rootId))
            {
                var thread = await ChatService.GetThreadAsync(rootId);
                if (thread.Count > 0)
                {
                    replyCounts[rootId] = thread.Count;
                }
            }
        }

        threadReplyCounts = replyCounts;
    }

    public async ValueTask DisposeAsync()
    {
        await cts.CancelAsync();
        cts.Dispose();
        dotNetRef?.Dispose();
        if (scrollModule is not null)
        {
            await scrollModule.DisposeAsync();
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    background: #313338;
    color: #dcddde;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 260px;
    max-width: 400px;
    flex-shrink: 0;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #8b949e;
    font-size: 1.1rem;
}

export function initScrollDetection(selector, dotNetRef) {
    const container = document.querySelector(selector);
    if (!container) return;

    container.addEventListener('scroll', () => {
        if (container.scrollTop <= 20) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    });
}

